#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\"\"\"\nImage Processing Application - برنامج معالجة الصور المتكامل\nكود واحد متكامل - لا توجد ملفات منفصلة\n\"\"\"\n\nimport cv2\nimport numpy as np\nfrom PIL import Image, ImageEnhance, ImageFilter, ImageOps\nfrom pathlib import Path\nimport os\nfrom typing import Optional\n\n\nclass ImageProcessor:\n    \"\"\"فئة معالجة الصور المتكاملة\"\"\"\n    \n    def __init__(self):\n        self.image = None\n        self.original_image = None\n        self.image_path = None\n        \n    def load_image(self, image_path: str) -> bool:\n        \"\"\"تحميل الصورة\"\"\"\n        try:\n            self.image_path = image_path\n            self.image = Image.open(image_path)\n            if self.image.mode not in {'RGB', 'L', 'RGBA'}:\n                self.image = self.image.convert('RGB')\n            else:\n                self.image = self.image.convert('RGB')\n            self.original_image = self.image.copy()\n            print(f\"✅ تم تحميل الصورة: {image_path}\")\n            print(f\"   الحجم: {self.image.size[0]}x{self.image.size[1]}\")\n            return True\n        except Exception as e:\n            print(f\"❌ خطأ في تحميل الصورة: {e}\")\n            return False\n    \n    def save_image(self, output_path: str) -> bool:\n        \"\"\"حفظ الصورة\"\"\"\n        try:\n            self.image.save(output_path)\n            print(f\"💾 تم حفظ الصورة: {output_path}\")\n            return True\n        except Exception as e:\n            print(f\"❌ خطأ في حفظ الصورة: {e}\")\n            return False\n    \n    def to_grayscale(self) -> 'ImageProcessor':\n        \"\"\"تحويل الصورة إلى رمادي\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        self.image = ImageOps.grayscale(self.image).convert('RGB')\n        print(\"✅ تم التحويل إلى رمادي\")\n        return self\n    \n    def resize(self, width: int, height: Optional[int] = None) -> 'ImageProcessor':\n        \"\"\"تغيير حجم الصورة\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        \n        if height is None:\n            ratio = width / self.image.size[0]\n            height = int(self.image.size[1] * ratio)\n        \n        self.image = self.image.resize((width, height), Image.Resampling.LANCZOS)\n        print(f\"✅ تم تغيير الحجم إلى {width}x{height}\")\n        return self\n    \n    def rotate(self, angle: int) -> 'ImageProcessor':\n        \"\"\"تدوير الصورة\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        self.image = self.image.rotate(angle, expand=True, fillcolor=(255, 255, 255))\n        print(f\"✅ تم تدوير الصورة بزاوية {angle} درجة\")\n        return self\n    \n    def adjust_brightness(self, factor: float) -> 'ImageProcessor':\n        \"\"\"ضبط السطوع\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        enhancer = ImageEnhance.Brightness(self.image)\n        self.image = enhancer.enhance(factor)\n        print(f\"✅ تم ضبط السطوع بمعامل {factor}\")\n        return self\n    \n    def adjust_contrast(self, factor: float) -> 'ImageProcessor':\n        \"\"\"ضبط التباين\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        enhancer = ImageEnhance.Contrast(self.image)\n        self.image = enhancer.enhance(factor)\n        print(f\"✅ تم ضبط التباين بمعامل {factor}\")\n        return self\n    \n    def apply_blur(self, radius: float) -> 'ImageProcessor':\n        \"\"\"تطبيق ضبابية\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        self.image = self.image.filter(ImageFilter.GaussianBlur(radius=radius))\n        print(f\"✅ تم تطبيق ضبابية بنصف قطر {radius}\")\n        return self\n    \n    def apply_sharpen(self) -> 'ImageProcessor':\n        \"\"\"تحديد الحواف\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        self.image = self.image.filter(ImageFilter.SHARPEN)\n        print(f\"✅ تم تحديد الحواف\")\n        return self\n    \n    def apply_edge_detection(self) -> 'ImageProcessor':\n        \"\"\"كشف الحواف\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        gray = cv2.cvtColor(np.array(self.image), cv2.COLOR_RGB2GRAY)\n        edges = cv2.Canny(gray, 100, 200)\n        self.image = Image.fromarray(edges).convert('RGB')\n        print(f\"✅ تم كشف الحواف\")\n        return self\n    \n    def apply_threshold(self, threshold_value: int) -> 'ImageProcessor':\n        \"\"\"تطبيق عتبة (تحوي�� إلى أبيض وأسود)\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        gray = cv2.cvtColor(np.array(self.image), cv2.COLOR_RGB2GRAY)\n        _, thresholded = cv2.threshold(gray, threshold_value, 255, cv2.THRESH_BINARY)\n        self.image = Image.fromarray(thresholded)\n        print(f\"✅ تم تطبيق عتبة {threshold_value}\")\n        return self\n    \n    def apply_histogram_equalization(self) -> 'ImageProcessor':\n        \"\"\"معادلة الهستوجرام (تحسين التباين)\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        img_cv = cv2.cvtColor(np.array(self.image), cv2.COLOR_RGB2BGR)\n        img_yuv = cv2.cvtColor(img_cv, cv2.COLOR_BGR2YCrCb)\n        img_yuv[:,:,0] = cv2.equalizeHist(img_yuv[:,:,0])\n        img_output = cv2.cvtColor(img_yuv, cv2.COLOR_YCrCb2BGR)\n        self.image = Image.fromarray(cv2.cvtColor(img_output, cv2.COLOR_BGR2RGB))\n        print(f\"✅ تم تطبيق معادلة الهستوجرام\")\n        return self\n    \n    def flip_horizontal(self) -> 'ImageProcessor':\n        \"\"\"قلب الصورة أفقياً\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        self.image = ImageOps.mirror(self.image)\n        print(f\"✅ تم قلب الصورة أفقياً\")\n        return self\n    \n    def flip_vertical(self) -> 'ImageProcessor':\n        \"\"\"قلب الصورة عمودياً\"\"\"\n        if self.image is None:\n            print(\"❌ لم يتم تحميل صورة!\")\n            return self\n        self.image = ImageOps.flip(self.image)\n        print(f\"✅ تم قلب الصورة عمودياً\")\n        return self\n    \n    def reset(self) -> 'ImageProcessor':\n        \"\"\"إعادة تعيين الصورة للأصل\"\"\"\n        if self.original_image is None:\n            print(\"❌ لا توجد صورة أصلية!\")\n            return self\n        self.image = self.original_image.copy()\n        print(f\"✅ تم إعادة تعيين الصورة\")\n        return self\n    \n    def show_menu(self):\n        \"\"\"عرض القائمة الرئيسية\"\"\"\n        print(\"\\n\" + \"=\"*60)\n        print(\"         برنامج معالجة الصور المتكامل\")\n        print(\"=\"*60)\n        print(\"1.  تحميل صورة\")\n        print(\"2.  تحويل إلى رمادي\")\n        print(\"3.  تغيير الحجم\")\n        print(\"4.  تدوير الصورة\")\n        print(\"5.  ضبط السطوع\")\n        print(\"6.  ضبط التباين\")\n        print(\"7.  تطبيق ضبابية\")\n        print(\"8.  تحديد الحواف\")\n        print(\"9.  كشف الحواف\")\n        print(\"10. تطبيق عتبة (أبيض/أسود)\")\n        print(\"11. معادلة الهستوجرام\")\n        print(\"12. قلب أفقي\")\n        print(\"13. قلب عمودي\")\n        print(\"14. إعادة تعيين\")\n        print(\"15. حفظ الصورة\")\n        print(\"16. خروج\")\n        print(\"=\"*60)\n    \n    def run(self):\n        \"\"\"تشغيل البرنامج التفاعلي\"\"\"\n        while True:\n            self.show_menu()\n            choice = input(\"اختر عملية (1-16): \").strip()\n            \n            if choice == \"1\":\n                image_path = input(\"أدخل مسار الصورة: \").strip()\n                self.load_image(image_path)\n            \n            elif choice == \"2\":\n                self.to_grayscale()\n            \n            elif choice == \"3\":\n                try:\n                    width = int(input(\"أدخل العرض الجديد: \"))\n                    height_input = input(\"أدخل الارتفاع (أو اتركه فارغاً): \").strip()\n                    height = int(height_input) if height_input else None\n                    self.resize(width, height)\n                except ValueError:\n                    print(\"❌ إدخال غير صحيح!\")\n            \n            elif choice == \"4\":\n                try:\n                    angle = int(input(\"أدخل زاوية الدوران (بالدرجات): \"))\n                    self.rotate(angle)\n                except ValueError:\n                    print(\"❌ إدخال غير صحيح!\")\n            \n            elif choice == \"5\":\n                try:\n                    factor = float(input(\"أدخل معامل السطوع (1.0 = عادي): \"))\n                    self.adjust_brightness(factor)\n                except ValueError:\n                    print(\"❌ إدخال غير صحيح!\")\n            \n            elif choice == \"6\":\n                try:\n                    factor = float(input(\"أدخل معامل التباين (1.0 = عادي): \"))\n                    self.adjust_contrast(factor)\n                except ValueError:\n                    print(\"❌ إدخال غير صحيح!\")\n            \n            elif choice == \"7\":\n                try:\n                    radius = float(input(\"أدخل نصف قطر الضبابية: \"))\n                    self.apply_blur(radius)\n                except ValueError:\n                    print(\"❌ إدخال غير صحيح!\")\n            \n            elif choice == \"8\":\n                self.apply_sharpen()\n            \n            elif choice == \"9\":\n                self.apply_edge_detection()\n            \n            elif choice == \"10\":\n                try:\n                    threshold = int(input(\"أدخل قيمة العتبة (0-255): \"))\n                    self.apply_threshold(threshold)\n                except ValueError:\n                    print(\"❌ إدخال غير صحيح!\")\n            \n            elif choice == \"11\":\n                self.apply_histogram_equalization()\n            \n            elif choice == \"12\":\n                self.flip_horizontal()\n            \n            elif choice == \"13\":\n                self.flip_vertical()\n            \n            elif choice == \"14\":\n                self.reset()\n            \n            elif choice == \"15\":\n                output_path = input(\"أدخل مسار الحفظ (مثال: output.jpg): \").strip()\n                self.save_image(output_path)\n            \n            elif choice == \"16\":\n                print(\"\\n👋 وداعاً!\")\n                break\n            \n            else:\n                print(\"❌ اختيار غير صحيح!\")\n            \n            input(\"\\nاضغط Enter للمتابعة...\")\n\n\ndef main():\n    \"\"\"البرنامج الرئيسي\"\"\"\n    processor = ImageProcessor()\n    processor.run()\n\n\nif __name__ == \"__main__\":\n    main()\n